        "hunks": [
          {
            "before": "// ---------------------------------------------------------------------------\n// KILL HANDLERS — the per-kind bounty registry consumed by World.kill().\n//\n// When an enemy falls, every registered rule whose tag/predicate matches runs\n// with a KillCtx: the kill-time window onto the world (credit, the zone, the\n",
            "after": "import {nativeWarlordCurrent,breakNativeWarlord} from './nativeWarlordIdentity';\n// ---------------------------------------------------------------------------\n// KILL HANDLERS — the per-kind bounty registry consumed by World.kill().\n//\n// When an enemy falls, every registered rule whose tag/predicate matches runs\n// with a KillCtx: the kill-time window onto the world (credit, the zone, the\n"
          },
          {
            "before": "// A slain warlord pays the player a bounty and a rival's gratitude.\n// (Its faction's power breaks in the next row — credit or not, the body counts.)\nregisterKillHandler({\n  id: 'warlord_bounty',\n  tag: 'warlord',\n  when: ctx => ctx.credit && !!ctx.actor.faction,\n  run: ctx => {\n    ctx.grantXp(200 + ctx.zone.level * 40);\n    ctx.dropGemAt(ctx.actor.pos);\n    ctx.dropGemAt(ctx.actor.pos);\n    const rival = Object.keys(FACTIONS).find(o => factionStance(ctx.actor.faction!, o) === 'hostile');\n    if (rival) ctx.sim.reputation.add(rival, 25);\n",
            "after": "// A slain warlord pays the player a bounty and a rival's gratitude.\n// (Its faction's power breaks in the next row — credit or not, the body counts.)\nregisterKillHandler({\n  id: 'warlord_bounty',\n  tag: 'warlord',\n  when: ctx => ctx.credit && !!ctx.actor.faction && nativeWarlordCurrent(ctx),\n  run: ctx => {\n    if (!nativeWarlordCurrent(ctx)) return;\n    ctx.grantXp(200 + ctx.zone.level * 40);\n    ctx.dropGemAt(ctx.actor.pos);\n    ctx.dropGemAt(ctx.actor.pos);\n    const rival = Object.keys(FACTIONS).find(o => factionStance(ctx.actor.faction!, o) === 'hostile');\n    if (rival) ctx.sim.reputation.add(rival, 25);\n"
          },
          {
            "before": "// Whoever lands the blow, a warlord's fall breaks its faction's power and\n// stills its wars — the field state must track the body, credit or not.\nregisterKillHandler({\n  id: 'warlord_break',\n  tag: 'warlord',\n  when: ctx => !!ctx.actor.faction,\n  run: ctx => {\n    ctx.sim.warlord.onWarlordKilled(ctx.actor.faction!, ctx.time, ctx.simView());\n    ctx.bumpLedger('warlords_killed'); // → unlocks Demon Invasions\n    const fname = (FACTIONS[ctx.actor.faction!]?.name ?? ctx.actor.faction!).replace(/^the /, '');\n    ctx.notice(`${fname} warlord slain! Their power breaks.`, '#ffd700', 18, 'war');\n  },\n});\n",
            "after": "// Whoever lands the blow, a warlord's fall breaks its faction's power and\n// stills its wars — the field state must track the body, credit or not.\nregisterKillHandler({\n  id: 'warlord_break',\n  tag: 'warlord',\n  when: ctx => !!ctx.actor.faction && nativeWarlordCurrent(ctx),\n  run: ctx => {\n    if (!breakNativeWarlord(ctx)) return;\n    ctx.bumpLedger('warlords_killed'); // → unlocks Demon Invasions\n    const fname = (FACTIONS[ctx.actor.faction!]?.name ?? ctx.actor.faction!).replace(/^the /, '');\n    ctx.notice(`${fname} warlord slain! Their power breaks.`, '#ffd700', 18, 'war');\n  },\n});\n"
          }
        ],
        "rawBeforeHash": "e4ca7da6a970a316e37e2a7efad2b6c7b8276b3186c410691d373d5cacf19c6d",
